// A tiny shop's sales, in place of a database. The agent asks; the tool answers with figures.
const sales = [
  { month: '2026-08', region: 'North', product: 'Kettle',  units: 120, revenue: 4800 },
  { month: '2026-08', region: 'South', product: 'Kettle',  units: 95,  revenue: 3800 },
  { month: '2026-08', region: 'North', product: 'Toaster', units: 40,  revenue: 2400 },
  { month: '2026-09', region: 'North', product: 'Kettle',  units: 130, revenue: 5200 },
  { month: '2026-09', region: 'South', product: 'Toaster', units: 75,  revenue: 4500 },
  { month: '2026-09', region: 'South', product: 'Kettle',  units: 60,  revenue: 2400 },
  { month: '2026-10', region: 'North', product: 'Toaster', units: 90,  revenue: 5400 },
  { month: '2026-10', region: 'South', product: 'Kettle',  units: 150, revenue: 6000 },
  { month: '2026-10', region: 'North', product: 'Kettle',  units: 70,  revenue: 2800 },
];
const q = String(query ?? '').toLowerCase();
const rows = sales.filter(r => !q || q === 'all' || Object.values(r).some(v => q.includes(String(v).toLowerCase())));
const totals = {};
for (const r of rows) totals[r.month] = (totals[r.month] ?? 0) + r.revenue;
return JSON.stringify({ rows: rows.length ? rows : sales, revenue_by_month: totals });
